// pickDest returns a live worker id other than the current owner of key.
func pickDest(c *Cluster, key string) string {
	cur := c.ownerOf(key)
	for _, id := range []string{"w0", "w1", "w2"} {
		if id != cur {
			return id
		}
	}
	return cur
}

// migrateWithCrash runs the handoff state machine by hand and injects a crash
// at a chosen point, then recovers using only the durable checkpoint store.
func migrateWithCrash(c *Cluster, key, dst, point string) {
	src := c.ownerOf(key)
	if src == dst {
		dst = pickDest(c, key)
	}
	ep := c.Epochs[key] + 1

	// (1) quiesce + durable snapshot
	cp := c.Workers[src].Freeze(key, ep, c.Cfg)
	c.Store.Put(cp)

	if point == "before-install" {
		c.SimulateCrashDst(dst, key)
	}
	if !c.InstallFromStore(key, dst, c.Cfg) {
		panic("recovery failed: no checkpoint")
	}
	// Retry install to model duplicate transfer delivery: must be idempotent.
	c.InstallFromStore(key, dst, c.Cfg)

	if point == "after-install-before-commit" {
		c.SimulateCrashDst(dst, key)
		if !c.InstallFromStore(key, dst, c.Cfg) {
			panic("recovery failed after target crash")
		}
	}

	// (3) fence switch
	c.Owners[key] = dst
	c.Epochs[key] = ep

	if point == "after-commit-before-release" {
		c.SimulateCrashSrc(src, key)
	} else {
		c.Workers[src].Release(key, ep)
	}
	c.flush(key)
}

func run(c *Cluster, migrating bool, crashPoint string) {
	migrate := func(key string) {
		if !migrating {
			return
		}
		dst := pickDest(c, key)
		if crashPoint == "none" {
			c.Migrate(key, dst)
		} else {
			migrateWithCrash(c, key, dst, crashPoint)
		}
	}
	keys := []string{"u1", "u2", "u3"}
	for round := 0; round < 9; round++ {
		base := int64(round * 100)
		for _, k := range keys {
			c.Ingest(ev(fmt.Sprintf("r-%s-%d", k, round), k, "R", base+20, base, base+40, Insert))
		}
		if round == 3 {
			migrate("u1")
			migrate("u2")
		}
		for _, k := range keys {
			c.Ingest(ev(fmt.Sprintf("l-%s-%d", k, round), k, "L", base+30, base+10, base+50, Insert))
		}
		if round == 3 {
			c.Ingest(ev("r-u1-3", "u1", "R", base+20, base, base+40, Insert))
		}
		if round == 5 {
			c.AdvanceWM("L", base+30)
			c.AdvanceWM("R", base+20)
		}
		if round == 6 {
			c.Ingest(ev("r-u2-2", "u2", "R", 220, 200, 240, Retract))
		}
		if round == 7 {
			migrate("u3")
		}
	}
	migrate("u1")
	c.AdvanceWM("L", 1<<40)
	c.AdvanceWM("R", 1<<40)
}

func TestMigrationMatchesBaseline(t *testing.T) {
	base := NewCluster(Config{AllowedLateness: 10, MaxIntervalLen: 50}, "w0")
	run(base, false, "none")
	want := base.Sink.Snapshot()
	if len(want) == 0 {
		t.Fatal("baseline produced no results")
	}

	crashes := []string{"none", "before-install", "after-install-before-commit", "after-commit-before-release"}
	for _, cp := range crashes {
		t.Run("crash="+cp, func(t *testing.T) {
			c := NewCluster(Config{AllowedLateness: 10, MaxIntervalLen: 50}, "w0", "w1", "w2")
			run(c, true, cp)
			got := c.Sink.Snapshot()
			if fmt.Sprint(got) != fmt.Sprint(want) {
				t.Fatalf("migration result diverged\n got=%v\nwant=%v", got, want)
			}
			if c.Sink.Applied != len(c.Sink.State) {
				t.Fatalf("sink double-counted: applied=%d distinct=%d", c.Sink.Applied, len(c.Sink.State))
			}
		})
	}
}

// A stale owner emitting after the fence switch must not flip materialized
// state produced by the new owner.
func TestEpochFencingRejectsStaleOwner(t *testing.T) {
	c := NewCluster(Config{AllowedLateness: 10, MaxIntervalLen: 50}, "w0", "w1")
	c.Ingest(ev("r1", "u1", "R", 100, 90, 120, Insert))
	c.Epochs["u1"] = 1
	staleEpoch := uint64(0)
	ch := Change{MatchID: "L:l1|R:r1", Key: "u1", L: "l1", R: "r1", Action: Insert}
	c.Sink.Apply(ch, 1, 1)
	c.Sink.Apply(Change{MatchID: ch.MatchID, Action: Retract}, staleEpoch, 1)
	if c.Sink.State[ch.MatchID] != Insert {
		t.Fatal("stale owner retract must be fenced")
	}
	if c.Sink.Fenced != 1 {
		t.Fatalf("expected 1 fenced write, got %d", c.Sink.Fenced)
	}
}

// Duplicate event delivery plus migration replay must not double count.
func TestDuplicatesAcrossMigrationAreIdempotent(t *testing.T) {
	c := NewCluster(Config{AllowedLateness: 10, MaxIntervalLen: 50}, "w0", "w1")
	c.Ingest(ev("r1", "u1", "R", 100, 90, 120, Insert))
	c.Ingest(ev("l1", "u1", "L", 105, 95, 115, Insert))
	before := c.Sink.Snapshot()

	dst := pickDest(c, "u1")
	c.Migrate("u1", dst)
	c.Ingest(ev("r1", "u1", "R", 100, 90, 120, Insert))
	c.Ingest(ev("l1", "u1", "L", 105, 95, 115, Insert))

	after := c.Sink.Snapshot()
	if fmt.Sprint(before) != fmt.Sprint(after) {
		t.Fatalf("duplicates changed result\nbefore=%v\nafter =%v", before, after)
	}
	if len(after) != 1 {
		t.Fatalf("expected exactly one materialized match, got %v", after)
	}
}

// The join state must stay bounded across a long out-of-order stream as the
// watermark advances. We prove this by running two histories of very
// different lengths and showing the final retained state is essentially
// identical (steady state depends only on the retention window L+D).
func TestBoundedStateUnderSustainedLoad(t *testing.T) {
	cfg := Config{AllowedLateness: 10, MaxIntervalLen: 50}
	runLen := func(n int) (live, matches int) {
		op := NewOperator(cfg)
		for i := 0; i < n; i++ {
			ts := int64(i)
			op.Apply(ev(fmt.Sprintf("r%d", i), "u1", "R", ts, ts-5, ts+5, Insert))
			op.Apply(ev(evID("l", i), "u1", "L", ts, ts-3, ts+7, Insert))
			op.AdvanceWM("L", ts)
			op.AdvanceWM("R", ts)
		}
		_, live, matches = op.StateSize()
		return
	}
	sLive, sMatch := runLen(10000)
	lLive, lMatch := runLen(40000)
	if lMatch > sMatch*2 || lLive > sLive*2 {
		t.Fatalf("state grows with history: short=(%d,%d) long=(%d,%d)", sLive, sMatch, lLive, lMatch)
	}
	t.Logf("short history=(live=%d matches=%d) long history=(live=%d matches=%d)", sLive, sMatch, lLive, lMatch)
}

func evID(prefix string, i int) string { return fmt.Sprintf("%s%d", prefix, i) }
